import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(t){return readFileSync(resolve(__dirname,"../../frontend/lalit-kala-akademi-award-explorer",t),"utf-8")}function readRootIndex(){return readFileSync(resolve(__dirname,"../../index.html"),"utf-8")}describe("Lalit Kala Akademi Award Explorer — Page Structure",()=>{let t;beforeAll(()=>{t=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(t).toContain('class="lka-hero"'),expect(t).toContain("<h1>"),expect(t).toContain("Lalit Kala Akademi")}),it("contains all required content sections",()=>{["history","eligibility","painting","sculpture","printmaking","ceramics","selection","awardees","gallery"].forEach(e=>{expect(t).toContain(`id="${e}"`),expect(t).toContain(`data-tab="${e}"`)})}),it("contains all required award categories as tab buttons",()=>{["Painting","Sculpture","Printmaking","Ceramics"].forEach(e=>{expect(t).toContain(e)})}),it("has a semantic heading hierarchy (single h1, section h2s)",()=>{const e=(t.match(/<h1[\s>]/g)||[]).length,a=(t.match(/<h2[\s>]/g)||[]).length;expect(e).toBe(1),expect(a).toBeGreaterThanOrEqual(9)}),it("uses HTTPS image sources with alt attributes",()=>{const e=t.match(/<img [^>]*>/g)||[];expect(e.length).toBeGreaterThanOrEqual(8),e.forEach(t=>{expect(t).toMatch(/src="https:\/\//),expect(t).toMatch(/alt="/),expect(t).not.toMatch(/src="http:\/\//)})}),it("links the shared stylesheet, page stylesheet, and script",()=>{expect(t).toContain('href="../../styles.css"'),expect(t).toContain('href="style.css"'),expect(t).toContain('src="script.js"')})}),describe("Lalit Kala Akademi Award Explorer — Assets",()=>{it("includes a non-empty stylesheet",()=>{const t=readExplorerFile("style.css");expect(t.length).toBeGreaterThan(1e3)}),it("includes a valid interactive script with required functions",()=>{const t=readExplorerFile("script.js");expect(t).toContain("initTabNavigation"),expect(t).toContain("activateTab"),expect(t).toContain("initCountUp"),expect(t).toContain("initTyping"),expect(t).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Lalit Kala Akademi Award — Landing Page Integration",()=>{it("is listed as a card on the Awards of India Explorer landing page",()=>{const t=readRootIndex();expect(t).toContain("Lalit Kala Akademi Award"),expect(t).toContain("frontend/lalit-kala-akademi-award-explorer/index.html")}),it("matches the existing award card pattern (icon, category, stats, button)",()=>{const t=readRootIndex(),e=t.indexOf("Lalit Kala Akademi Award Card");expect(e).toBeGreaterThan(-1);const a=t.slice(e,e+900);expect(a).toContain("award-card-icon"),expect(a).toContain("award-category"),expect(a).toContain("award-stats"),expect(a).toContain("award-btn"),expect(a).toContain('class="award-card glass-card"')})});